import axios, { AxiosInstance } from 'axios';
import JSONBig from 'json-bigint';
import { createModuleLogger } from '../utils/logger';
// P5: 导入数据库连接用于异步报告队列
import { getDb } from '../db';
// P5: 静态导入reportJobs表（避免动态import在esbuild中无法解析）
