  /**
   * 下载报告数据
   */
  async downloadReport(url: string, retries: number = 3): Promise<Record<string, unknown>[]> {
    // v449: 增强报告下载 — 添加超时、重试机制，解决SB搜索词报告下载超时问题
    for (let attempt = 1; attempt <= retries; attempt++) {
      try {
        const response = await axios.get(url, {
          responseType: 'stream',
          timeout: 120000, // v449: 120秒连接+响应超时
        });
        
        const zlib = await import('zlib');
        
        const data = await new Promise<Record<string, unknown>[]>((resolve, reject) => {
          const chunks: Buffer[] = [];
          let totalSize = 0;
          const MAX_SIZE = 500 * 1024 * 1024; // 500MB限制
          
          // v449: 流级别超时 — 如果120秒内没有新数据到达，中断下载
          let lastDataTime = Date.now();
          const STREAM_IDLE_TIMEOUT = 120000;
          const idleTimer = setInterval(() => {
            if (Date.now() - lastDataTime > STREAM_IDLE_TIMEOUT) {
              clearInterval(idleTimer);
              gunzip.destroy();
              reject(new Error(`Stream idle timeout: no data received for ${STREAM_IDLE_TIMEOUT / 1000}s`));
            }
          }, 10000);
          
          const gunzip = zlib.createGunzip();
          
          response.data
            .pipe(gunzip)
            .on('data', (chunk: Buffer) => {
              lastDataTime = Date.now();
              totalSize += chunk.length;
              if (totalSize > MAX_SIZE) {
                clearInterval(idleTimer);
                gunzip.destroy();
                reject(new Error(`Report too large: ${totalSize} bytes exceeds ${MAX_SIZE} bytes limit`));
                return;
              }
              chunks.push(chunk);
            })
            .on('end', () => {
              clearInterval(idleTimer);
              try {
                const data = Buffer.concat(chunks).toString('utf-8');
                const result = JSON.parse(data);
                log.info(`[Amazon API] v449: 报告解压完成，原始大小: ${totalSize} bytes, 数据条数: ${result?.length || 0}, 尝试: ${attempt}/${retries}`);
                resolve(result);
              } catch (parseError: unknown) {
                reject(new Error(`Failed to parse report JSON: ${(parseError as Error).message}`));
              }
            })
            .on('error', (err: Error) => {
              clearInterval(idleTimer);
              reject(new Error(`Failed to decompress report: ${(err as Error).message}`));
            });
        });
        
        return data;
      } catch (downloadErr: unknown) {
        const errMsg = (downloadErr as Error).message || '';
        log.warn(`[Amazon API] v449: 报告下载失败(尝试${attempt}/${retries}): ${errMsg}`);
        if (attempt >= retries) {
          throw new Error(`Report download failed after ${retries} attempts: ${errMsg}`);
        }
        // v449: 指数退避重试 — 5s, 10s, 20s
        const backoff = Math.min(5000 * Math.pow(2, attempt - 1), 20000);
        log.info(`[Amazon API] v449: ${backoff / 1000}秒后重试下载...`);
        await new Promise(resolve => setTimeout(resolve, backoff));
      }
    }
    throw new Error('Unreachable: download retry loop exited without result');
  }

  /**
   * 等待报告完成并下载
   * v413: 智能退避优化 — 指数退避轮询(5s→10s→20s→30s) + 缩短默认超时(15分钟→5分钟) + 连续PENDING检测
   */
  async waitAndDownloadReport(reportId: string, maxWaitMs: number = 600000): Promise<Record<string, unknown>[]> {  // v454: 超时从5分钟增加到10分钟
    const startTime = Date.now();
    let pollCount = 0;
    // v413: 指数退避轮询间隔：5s → 10s → 20s → 30s(封顶)
    const getPollInterval = (count: number): number => {
      const intervals = [5000, 10000, 20000, 30000];
      return intervals[Math.min(count, intervals.length - 1)];
    };
    
    log.info(`[Amazon API] v413: 开始等待报告完成: ${reportId}, 超时=${Math.round(maxWaitMs / 1000)}秒`);
    
    while (Date.now() - startTime < maxWaitMs) {
      try {
        const status = await this.getReportStatus(reportId);
        
        if (status.status === 'COMPLETED' && status.url) {
          const waitSec = Math.round((Date.now() - startTime) / 1000);
          log.info(`[Amazon API] v413: 报告已完成，等待${waitSec}秒，轮询${pollCount}次，开始下载...`);
          const data = await this.downloadReport(status.url);
          log.info(`[Amazon API] v413: 报告下载完成，数据条数: ${data?.length || 0}`);
          return data;
        }
        
        if (status.status === 'FAILED') {
          const failReason = status.failureReason || 'unknown';
          log.warn(`[Amazon API] v413: 报告生成失败: ${failReason}`);
          throw new Error(`Report generation failed: ${failReason}`);
        }
        
        // v413: 指数退避轮询
        const interval = getPollInterval(pollCount);
        pollCount++;
        const elapsedSec = Math.round((Date.now() - startTime) / 1000);
        // v413: 减少日志刷屏 — 前3次每次记录，之后每5次记录一次
        if (pollCount <= 3 || pollCount % 5 === 0) {
          log.info(`[Amazon API] v413: 报告${reportId.slice(-8)} PENDING, 已等${elapsedSec}秒, 轮询#${pollCount}, 下次${interval / 1000}秒后`);
        }
        await new Promise(resolve => setTimeout(resolve, interval));
      } catch (pollErr: unknown) {
        // v413: 轮询过程中的网络错误不立即抛出，而是等待后重试
        const errMsg = (pollErr as Error).message || '';
        if (errMsg.includes('Report generation failed')) {
          throw pollErr; // 报告确认失败，直接抛出
        }
        // @ts-expect-error - legacy type assertion
        pollCount++;
        const interval = getPollInterval(pollCount);
        log.warn(`[Amazon API] v413: 轮询报告状态失败(#${pollCount}): ${errMsg}，${interval / 1000}秒后重试`);
        await new Promise(resolve => setTimeout(resolve, interval));
      }
    }
    
    const totalSec = Math.round((Date.now() - startTime) / 1000);
    log.warn(`[Amazon API] v413: 报告生成超时 - reportId=${reportId}, 等待${totalSec}秒, 轮询${pollCount}次`);
    throw new Error(`Report generation timeout after ${totalSec}s (${pollCount} polls)`);
  }

